#include "entity_controller.hpp"
#include <cassert>
struct W:shin::EntityWorld {int n=0;int camera_x()const override{return 0;}int camera_y()const override{return 0;}bool render_tick()const override{return true;}int player_x()const override{return 600;}int player_width()const override{return 40;}void register_collision(shin::EntityState&,unsigned,unsigned)override{++n;}void respawn_record(const shin::EntityState&,unsigned,unsigned)override{++n;}void render(const shin::EntityState&,int,int,unsigned,unsigned)override{}void spawn_projectile(int,int,int,int,int,unsigned)override{++n;}void defeated(const shin::EntityState&)override{++n;}};
int main(){W w;shin::EntityController turn(0,100,0,0,w);turn.platform(2);assert(turn.state().state==2);turn.platform(0);assert(turn.state().state==0);turn.state().state=3;turn.platform(1);assert(turn.state().state==3);w.n=0;shin::EntityController e(1,320,0,0,w);e.update(w);assert(e.state().x==319&&e.state().y==1);e.state().attack_tick=200;e.update(w);assert(e.state().state==3);e.state().frame=2;e.state().frame_tick=9;e.update(w);assert(w.n==2&&e.state().state==1);e.state().x=2000;e.update(w);assert(e.state().pending_delete&&w.n==3);shin::EntityController dead(1,2000,0,0,w);dead.state().state=4;int before=w.n;dead.update(w);assert(w.n==before&&dead.state().pending_delete);}
